// Source of truth: logic/crm.js. Set CRM_ADAPTER (env var) to the CRM you run.
// Supported: 'generic' (any REST CRM), 'hubspot', 'gohighlevel', 'pipedrive'.
// See docs/CRM-MAPPING.md before adding a new one.
const CRM_ADAPTERS = ['generic', 'hubspot', 'gohighlevel', 'pipedrive'];
const CRM_ADAPTER = $env.CRM_ADAPTER || 'generic';

function nonEmpty(o) {
  const out = {};
  for (const k of Object.keys(o)) {
    const v = o[k];
    if (v !== null && v !== undefined && v !== '') out[k] = v;
  }
  return out;
}
function splitName(name) {
  const n = (name || '').trim();
  if (!n) return { first: '', last: '' };
  const p = n.split(/\s+/);
  return { first: p[0], last: p.slice(1).join(' ') };
}
function toCrmPayload(l) {
  const name = splitName(l.name);
  const tags = Array.isArray(l.tags) ? l.tags.slice() : [];
  if (l.band) tags.push('score:' + l.band);
  if (l.source) tags.push('source:' + l.source);
  if (CRM_ADAPTER === 'hubspot') {
    return { properties: nonEmpty({ email: l.email, phone: l.phone, firstname: name.first,
      lastname: name.last, company: l.company, hs_lead_status: l.band === 'hot' ? 'OPEN' : 'NEW',
      lifecyclestage: 'lead', lead_score_custom: l.score,
      lead_score_reasons: (l.score_reasons || []).join('; ') }) };
  }
  if (CRM_ADAPTER === 'gohighlevel') {
    return nonEmpty({ email: l.email, phone: l.phone, firstName: name.first, lastName: name.last,
      companyName: l.company, source: l.source, tags: tags, customFields: [
        { key: 'lead_score', field_value: String(l.score === undefined ? '' : l.score) },
        { key: 'lead_band', field_value: l.band || '' },
        { key: 'consent_basis', field_value: l.consent_basis || '' } ] });
  }
  if (CRM_ADAPTER === 'pipedrive') {
    return nonEmpty({ name: l.name, org_name: l.company, label: l.band, visible_to: '3' });
  }
  return nonEmpty({ email: l.email, phone: l.phone, name: l.name, company: l.company,
    domain: l.domain, source: l.source, campaign: l.campaign, score: l.score, band: l.band,
    score_reasons: l.score_reasons, consent_basis: l.consent_basis, tags: tags, notes: l.notes });
}

return $input.all().map((item) => {
  const lead = Object.assign({ source: '%s' }, item.json.lead || item.json);
  return { json: Object.assign({}, item.json, {
    lead,
    crm_adapter: CRM_ADAPTER,
    crm_payload: toCrmPayload(lead),
    crm_match_value: lead.email || lead.phone || lead.name || ''
  }) };
});
